import json, random, subprocess, sys, resource, time, os
def run_limited(data, mem_kb=1048576):
    def pre():
        resource.setrlimit(resource.RLIMIT_AS, (mem_kb*1024, mem_kb*1024))
    t0=time.time()
    p=subprocess.run([sys.executable,"-I","submission/main.py"],input=data,capture_output=True,preexec_fn=pre)
    return p.returncode, len(p.stdout), time.time()-t0, p.stderr.decode()[-200:]

# max path/class case: 8192 paths
def layered(width, layers, offset=0):
    edges=[]
    def e(u,v): edges.append({"u":u,"v":v,"ping_us":1,"ack_us":2,"label":"%d%d"%(u%10,v%10)})
    src=offset; pre=offset+1
    e(src,pre)
    first=pre+1
    for k in range(width): e(pre, first+k)
    for L in range(layers-1):
        b=first+L*width; nx=first+(L+1)*width
        for a in range(width):
            for b2 in range(width): e(b+a, nx+b2)
    last=first+(layers-1)*width; dest=last+width
    for k in range(width): e(last+k, dest)
    return dest+1, edges
n,edges = layered(2,13)
assert n-1 == max(e["v"] for e in edges)
R=48
rounds=[{"launch_us":i,"timeout_us":100,"host_delay_us":3,"drop_host_ack":False,
         "drop_ping":[],"drop_ack":[]} for i in range(R)]
obj={"version":1,"n":n,"capacity":[8]*n,"edges":edges,"rounds":rounds}
print("8192-path all-delivered:", run_limited(json.dumps(obj).encode()))
PYEOF
